-- Existing fictional QA fixture only. SELECT-only operator rehearsal; not RLS/JWT acceptance.
-- Credential/provider-token tables are count-only. No Auth/session/secret values exported.
WITH fixture AS (
 SELECT b.id,m.user_id FROM public.businesses b
 JOIN public.business_memberships m ON m.business_id=b.id
 JOIN auth.users u ON u.id=m.user_id
 WHERE b.id='433f135d-720f-4687-8114-3dffe7361675'::uuid
 AND b.name='QA Example Garden B — TEST ONLY'
 AND m.user_id='b8cb079d-792e-4810-8218-0f9d442c521a'::uuid AND m.role='owner'
 AND u.email='08collinsj+colzoqa@gmail.com'
 AND (SELECT count(*) FROM public.business_memberships x WHERE x.business_id=b.id)=1
), categories AS (
select 'actions'::text category,jsonb_build_object('mode','data','row_count',(select count(*) from public."actions" s join fixture f on s.business_id=f.id),'rows',coalesce((select jsonb_agg(to_jsonb(d) order by to_jsonb(d)::text) from (select s."id",s."business_id",s."lead_id",s."booking_id",s."title",s."description",s."action_type",s."due_at",s."priority",s."status",s."completed_at",s."created_at",s."updated_at" from public."actions" s join fixture f on s.business_id=f.id) d),'[]'::jsonb)) payload
UNION ALL
select 'bookings'::text category,jsonb_build_object('mode','data','row_count',(select count(*) from public."bookings" s join fixture f on s.business_id=f.id),'rows',coalesce((select jsonb_agg(to_jsonb(d) order by to_jsonb(d)::text) from (select s."id",s."business_id",s."lead_id",s."title",s."customer_name",s."customer_phone",s."customer_email",s."starts_at",s."ends_at",s."location",s."status",s."notes",s."source",s."created_at",s."updated_at",s."review_email_allowed" from public."bookings" s join fixture f on s.business_id=f.id) d),'[]'::jsonb)) payload
