select 'shared_referrals'::text category,jsonb_build_object('mode','count_only','row_count',(select count(*) from public.business_referrals s join fixture f on s.referrer_business_id=f.id or s.referred_business_id=f.id),'rows','[]'::jsonb) payload
)
SELECT CASE WHEN (SELECT count(*) FROM fixture)=1 THEN
 jsonb_build_object('format_version',1,'business_id',(select id from fixture),
 'user_id',(select user_id from fixture),'captured_at',statement_timestamp(),
 'categories',(select jsonb_object_agg(category,payload) from categories))
 ELSE jsonb_build_object('error','fixture mapping mismatch') END AS fixture_export;
